                }

                if ($partial && $this->collTaskInstances) {
                    foreach ($this->collTaskInstances as $obj) {
                        if ($obj->isNew()) {
                            $collTaskInstances[] = $obj;
                        }
                    }
                }

                $this->collTaskInstances = $collTaskInstances;
                $this->collTaskInstancesPartial = false;
            }
        }

        return $this->collTaskInstances;
    }

    /**
     * Sets a collection of TaskInstance objects related by a one-to-many relationship
     * to the current object.
     * It will also schedule objects for deletion based on a diff between old objects (aka persisted)
     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $taskInstances A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return WorkflowInstance The current object (for fluent API support)
     */
    public function setTaskInstances(PropelCollection $taskInstances, PropelPDO $con = null)
    {
        $taskInstancesToDelete = $this->getTaskInstances(new Criteria(), $con)->diff($taskInstances);


        $this->taskInstancesScheduledForDeletion = $taskInstancesToDelete;

        foreach ($taskInstancesToDelete as $taskInstanceRemoved) {
            $taskInstanceRemoved->setWorkflowInstance(null);
        }

        $this->collTaskInstances = null;
        foreach ($taskInstances as $taskInstance) {
            $this->addTaskInstance($taskInstance);
        }

        $this->collTaskInstances = $taskInstances;
        $this->collTaskInstancesPartial = false;

        return $this;
    }

    /**
     * Returns the number of related TaskInstance objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related TaskInstance objects.
     * @throws PropelException
     */
    public function countTaskInstances(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collTaskInstancesPartial && !$this->isNew();
        if (null === $this->collTaskInstances || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collTaskInstances) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getTaskInstances());
            }
            $query = TaskInstanceQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByWorkflowInstance($this)
                ->count($con);
        }

        return count($this->collTaskInstances);
    }

    /**
     * Method called to associate a TaskInstance object to this object
     * through the TaskInstance foreign key attribute.
     *
     * @param    TaskInstance $l TaskInstance
     * @return WorkflowInstance The current object (for fluent API support)
     */
    public function addTaskInstance(TaskInstance $l)
    {
        if ($this->collTaskInstances === null) {
            $this->initTaskInstances();
            $this->collTaskInstancesPartial = true;
        }

        if (!in_array($l, $this->collTaskInstances->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddTaskInstance($l);

            if ($this->taskInstancesScheduledForDeletion and $this->taskInstancesScheduledForDeletion->contains($l)) {
                $this->taskInstancesScheduledForDeletion->remove($this->taskInstancesScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	TaskInstance $taskInstance The taskInstance object to add.
     */
    protected function doAddTaskInstance($taskInstance)
    {
        $this->collTaskInstances[]= $taskInstance;
        $taskInstance->setWorkflowInstance($this);
    }

    /**
     * @param	TaskInstance $taskInstance The taskInstance object to remove.
     * @return WorkflowInstance The current object (for fluent API support)
     */
    public function removeTaskInstance($taskInstance)
    {
        if ($this->getTaskInstances()->contains($taskInstance)) {
            $this->collTaskInstances->remove($this->collTaskInstances->search($taskInstance));
            if (null === $this->taskInstancesScheduledForDeletion) {
                $this->taskInstancesScheduledForDeletion = clone $this->collTaskInstances;
                $this->taskInstancesScheduledForDeletion->clear();
            }
            $this->taskInstancesScheduledForDeletion[]= clone $taskInstance;
            $taskInstance->setWorkflowInstance(null);
        }

        return $this;
    }


