    /**
     * Clears the current object and sets all attributes to their default values
     */
    public function clear()
    {
        $this->workflowinstance_id = null;
        $this->bpmnprocess_id = null;
        $this->workflowstatus_id = null;
        $this->usuario_id = null;
        $this->bpmnsimulation_id = null;
        $this->nombre = null;
        $this->current_node = null;
        $this->variables = null;
        $this->fecha_inicio = null;
        $this->fecha_completado = null;
        $this->fecha_creacion = null;
        $this->fecha_modificacion = null;
        $this->prioridad = null;
        $this->is_simulation = null;
        $this->alreadyInSave = false;
        $this->alreadyInValidation = false;
        $this->alreadyInClearAllReferencesDeep = false;
        $this->clearAllReferences();
        $this->applyDefaultValues();
        $this->resetModified();
        $this->setNew(true);
        $this->setDeleted(false);
    }

    /**
     * Resets all references to other model objects or collections of model objects.
     *
     * This method is a user-space workaround for PHP's inability to garbage collect
     * objects with circular references (even in PHP 5.3). This is currently necessary
     * when using Propel in certain daemon or large-volume/high-memory operations.
     *
     * @param boolean $deep Whether to also clear the references on all referrer objects.
     */
    public function clearAllReferences($deep = false)
    {
        if ($deep && !$this->alreadyInClearAllReferencesDeep) {
            $this->alreadyInClearAllReferencesDeep = true;
            if ($this->collTaskAttachments) {
                foreach ($this->collTaskAttachments as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collWorkflowHistorys) {
                foreach ($this->collWorkflowHistorys as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTaskLogs) {
                foreach ($this->collTaskLogs as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTimerEvents) {
                foreach ($this->collTimerEvents as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->collTaskInstances) {
                foreach ($this->collTaskInstances as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aBpmnProcess instanceof Persistent) {
              $this->aBpmnProcess->clearAllReferences($deep);
            }
            if ($this->aWorkflowStatus instanceof Persistent) {
              $this->aWorkflowStatus->clearAllReferences($deep);
            }
            if ($this->aUsuario instanceof Persistent) {
              $this->aUsuario->clearAllReferences($deep);
            }
            if ($this->aBpmnSimulation instanceof Persistent) {
              $this->aBpmnSimulation->clearAllReferences($deep);
            }

            $this->alreadyInClearAllReferencesDeep = false;
        } // if ($deep)

        if ($this->collTaskAttachments instanceof PropelCollection) {
            $this->collTaskAttachments->clearIterator();
        }
        $this->collTaskAttachments = null;
        if ($this->collWorkflowHistorys instanceof PropelCollection) {
            $this->collWorkflowHistorys->clearIterator();
        }
        $this->collWorkflowHistorys = null;
        if ($this->collTaskLogs instanceof PropelCollection) {
            $this->collTaskLogs->clearIterator();
        }
        $this->collTaskLogs = null;
        if ($this->collTimerEvents instanceof PropelCollection) {
            $this->collTimerEvents->clearIterator();
        }
        $this->collTimerEvents = null;
        if ($this->collTaskInstances instanceof PropelCollection) {
            $this->collTaskInstances->clearIterator();
        }
        $this->collTaskInstances = null;
        $this->aBpmnProcess = null;
        $this->aWorkflowStatus = null;
        $this->aUsuario = null;
        $this->aBpmnSimulation = null;
    }

